# Just use inline transform
def find_dividing_lines(grid):
    h_lines = [i for i, row in enumerate(grid) if all(c == 2 for c in row)]
    v_lines = [j for j in range(len(grid[0])) if all(grid[i][j] == 2 for i in range(len(grid)))]
    return h_lines, v_lines

def find_marker(grid):
    import collections
    counts = collections.Counter(cell for row in grid for cell in row)
    non_line_counts = {k: v for k, v in counts.items() if k != 2}
    if len(non_line_counts) <= 1:
        return 2
    return min(non_line_counts.keys(), key=lambda x: non_line_counts[x])

def transform(grid):
    h_lines, v_lines = find_dividing_lines(grid)
    row_regions = [(0, h_lines[0])] if h_lines else []
    if h_lines:
        for i in range(len(h_lines)):
            if i < len(h_lines) - 1:
                row_regions.append((h_lines[i] + 1, h_lines[i+1] - 1))
            else:
                row_regions.append((h_lines[-1] + 1, len(grid) - 1))
    col_regions = [(0, v_lines[0])] if v_lines else []
    if v_lines:
        for i in range(len(v_lines)):
            if i < len(v_lines) - 1:
                col_regions.append((v_lines[i] + 1, v_lines[i+1] - 1))
            else:
                col_regions.append((v_lines[-1] + 1, len(grid[0]) - 1))
    marker = find_marker(grid)
    import collections as mc
    region_counts = mc.defaultdict(int)
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == marker:
                row_idx = next((i for i, reg in enumerate(row_regions) if reg[0] <= r <= reg[1]), None)
                col_idx = next((j for j, reg in enumerate(col_regions) if reg[0] <= c <= reg[1]), None)
                if row_idx is not None and col_idx is not None:
                    region_counts[(row_idx, col_idx)] += 1
    num_rows = len(row_regions)
    num_cols = len(col_regions)
    output = [[9] * num_cols for _ in range(num_rows)]
    for (r, c), count in region_counts.items():
        if count >= 2:
            output[r][c] = 1
    return output

